enum ProfileAudience { owner, closeFriends, followers, public }
enum ProfileVisibility { private, closeFriends, followers, public }
class ProfileFieldRule { const ProfileFieldRule({required this.field,required this.visibility}); final String field; final ProfileVisibility visibility; }
class ProfilePrivacyResolver { const ProfilePrivacyResolver(); bool canView({required String field,required ProfileAudience audience,required Iterable<ProfileFieldRule> rules,required bool blocked}){if(blocked||field.trim().isEmpty)return false;if(audience==ProfileAudience.owner)return true;ProfileVisibility? v;for(final r in rules){if(r.field==field){v=r.visibility;break;}}if(v==null||v==ProfileVisibility.private)return false;switch(v){case ProfileVisibility.private:return false;case ProfileVisibility.closeFriends:return audience==ProfileAudience.closeFriends;case ProfileVisibility.followers:return audience==ProfileAudience.closeFriends||audience==ProfileAudience.followers;case ProfileVisibility.public:return true;}}}
